#include <zephyr/ztest.h>
#include <zephyr/drivers/counter.h>
#include <zephyr/devicetree.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(counter_capture_test, LOG_LEVEL_DBG);

#define TEST_COUNTER_NODE DT_NODELABEL(test_counter)

#if !DT_NODE_HAS_STATUS(TEST_COUNTER_NODE, okay)
#error "test_counter devicetree node is not enabled"
#endif

struct counter_capture_cfg {
    const struct device *counter_dev;
    uint8_t channel_id;
    uint32_t flags;
};

/*
 * Macro to initialize a capture_cfg from devicetree properties.
 * A trailing comma is crucial for DT_FOREACH_PROP_ELEM to expand correctly.
 */
#define CAPTURE_CFG_INIT(node_id, prop, idx) \
    { \
        .counter_dev = DEVICE_DT_GET(DT_PHANDLE_BY_IDX(node_id, prop, idx)), \
        .channel_id = DT_PROP_BY_IDX(node_id, capture_channels, idx), \
        .flags = DT_PROP_BY_IDX(node_id, capture_flags, idx), \
    },

static const struct counter_capture_cfg capture_configs[] = {
    DT_FOREACH_PROP_ELEM(TEST_COUNTER_NODE, captures, CAPTURE_CFG_INIT)
};

/*
 * Define loopback counters from devicetree.
 * Ensure 'const struct device *' type is explicitly specified to avoid implicit-int errors.
 */
#define DEFINE_LOOPBACK_COUNTER(inst) \
    const struct device *counter_loopback_##inst = DEVICE_DT_GET(DT_INST_GET(inst));

DT_INST_FOREACH_STATUS_OKAY(test_counter_loopback, DEFINE_LOOPBACK_COUNTER)

struct counter_capture_fixture {
    const struct device *counter_dev;
    const struct counter_capture_cfg *cfg;
    struct k_sem capture_sem;
    uint32_t captured_value;
};

static void capture_callback(const struct device *dev, uint8_t chan_id, uint32_t ticks,
                             void *user_data)
{
    struct counter_capture_fixture *fixture = user_data;
    fixture->captured_value = ticks;
    k_sem_give(&fixture->capture_sem);
}

/* Test suite setup function */
static void counter_setup(void *f)
{
    struct counter_capture_fixture *fixture = f;

    fixture->counter_dev = DEVICE_DT_GET(TEST_COUNTER_NODE);
    zassert_not_null(fixture->counter_dev, "Counter device not found");

    k_sem_init(&fixture->capture_sem, 0, 1);

    /* Assume the first config for basic tests */
    zassert_true(ARRAY_SIZE(capture_configs) > 0, "No capture configurations defined");
    fixture->cfg = &capture_configs[0];

    int err = counter_set_channel_callback(fixture->counter_dev, fixture->cfg->channel_id,
                                           capture_callback, fixture);
    zassert_equal(err, 0, "Failed to set channel callback");

    err = counter_start(fixture->counter_dev);
    zassert_equal(err, 0, "Failed to start counter");
}

/* Test suite 'before' function (runs before each test case) */
static void counter_before(void *f)
{
    struct counter_capture_fixture *fixture = f;
    int err;

    /* Reset counter before each test */
    err = counter_stop(fixture->counter_dev);
    zassert_equal(err, 0, "Failed to stop counter");

    err = counter_set_top_value(fixture->counter_dev, counter_get_max_top_value(fixture->counter_dev), 0, 0);
    zassert_equal(err, 0, "Failed to set top value");

    err = counter_start(fixture->counter_dev);
    zassert_equal(err, 0, "Failed to start counter");

    k_sem_reset(&fixture->capture_sem);
}

/* Test suite 'after' function (runs after each test case) */
static void counter_after(void *f)
{
    struct counter_capture_fixture *fixture = f;
    int err;

    err = counter_stop(fixture->counter_dev);
    zassert_equal(err, 0, "Failed to stop counter");
}

/* Test suite teardown function */
static void counter_teardown(void *f)
{
    ARG_UNUSED(f);
    /* No specific teardown needed beyond stopping the counter in after() */
}

ZTEST_F(counter_capture, test_basic_capture)
{
    int err;
    uint32_t current_ticks;

    err = counter_capture_set(fixture->counter_dev, fixture->cfg->channel_id, fixture->cfg->flags);
    zassert_equal(err, 0, "Failed to set capture");

    /* Wait for capture event */
    k_sem_take(&fixture->capture_sem, K_MSEC(100));

    current_ticks = counter_get_value(fixture->counter_dev);
    LOG_DBG("Captured value: %u, Current ticks: %u", fixture->captured_value, current_ticks);

    /* The captured value should be close to the current ticks */
    zassert_true(fixture->captured_value <= current_ticks, "Captured value (%u) > current ticks (%u)",
                 fixture->captured_value, current_ticks);
    /* Allow for some small delay between capture and read */
    zassert_true((current_ticks - fixture->captured_value) < 10, "Difference too large");

    err = counter_capture_set(fixture->counter_dev, fixture->cfg->channel_id, 0); /* Disable capture */
    zassert_equal(err, 0, "Failed to disable capture");
}

ZTEST_F(counter_capture, test_loopback_capture)
{
    /* This test assumes a loopback counter is defined in devicetree and available. */
    const struct device *loopback_dev = counter_loopback_0; /* Assuming instance 0 */
    zassert_not_null(loopback_dev, "Loopback counter (instance 0) not found");

    /* Add specific test logic for loopback capture here */
    /* For example, trigger an event on the loopback counter and verify capture on main counter */
    LOG_INF("Loopback counter test placeholder");
}

/*
 * ZTEST_SUITE definition.
 * Ensure all setup/teardown functions are defined and passed correctly.
 * The last argument is the fixture type, not a variable.
 */
ZTEST_SUITE(counter_capture, counter_setup, counter_before, counter_after, counter_teardown,
            struct counter_capture_fixture);
